import json,sys,signal
R=Path.cwd();sys.path.insert(0,str(R/'tools/experiments'));import m7_apple_package as p
O=Path(__file__).resolve().parent
paths=[*p.numerical_sources(),R/'apple/include/toklet.h',R/'apple/include/module.modulemap',R/'apple/tests/native_smoke.c',Path(p.__file__).resolve(),R/'tools/experiments/test_m7_apple_package.py',Path(__file__).resolve()]
pins={str(f.relative_to(R)):p.sha(f) for f in paths};protected={'target/release/toklet':'5250694e814ea112148a52cfdeaf5bc6286ff2804b3acfd8f89e80bc73122a59','target/release/examples/cpu_bench':'e3debabbae7db9e5801bc9bfba177275444ebe1d9849eb3ad0f2dff487ac8dea'}
commands=[];primary=None;endpoints=[];previous=signal.signal(signal.SIGTERM,p.interrupted)
try:
 env,_=p.build_environment()
 for n,h in protected.items():assert p.sha(R/n)==h,n
 for label,cmd in [('portable',[sys.executable,'-m','unittest','discover','-s','tools/experiments','-p','test_m7_apple_package.py','-v']),('package',[sys.executable,'tools/experiments/m7_apple_package.py','artifacts/m8-apple-package-v1'])]:
  row=p.owned(cmd,O/(label+'.stdout'),O/(label+'.stderr'),env,1800);commands.append(row)
