 r=dict(format='toklet-mlx-apple-package-checks-v1',passed=primary is None and not endpoints,source_pins=pins,protected_binary_pins=protected,commands=commands,primary_error=primary,endpoint_errors=endpoints)
 with (O/'checks.json').open('x') as f:json.dump(r,f,indent=2);f.write('\n')
 print(json.dumps(dict(passed=r['passed'],commands=len(commands),primary_error=primary,endpoint_errors=endpoints)));sys.exit(0 if r['passed'] else 1)

